parameters.pythonCode:
output = []

for item in _items:
    result = item["json"].get("organic_results", [])

    first = result[0] if result else {}

    link = first.get("link", "")

    official_domain = (
        link.replace("https://", "")
            .replace("http://", "")
            .replace("www.", "")
            .split("/")[0]
        if link else ""
    )

    output.append({
        "json": {
            "company_name": first.get("title", ""),
            "official_domain": official_domain,
            "official_url": link
        }
    })

return output
